interface Client {
  id: number;
  nom: string;
  email?: string;          // propriété facultative
  readonly creeLe: string; // non modifiable après création
}

type Statut = "actif" | "suspendu" | "archive";
type Reponse =
  | { ok: true; donnees: Client }
  | { ok: false; erreur: string };

function traiter(r: Reponse) {
  if (r.ok) {
    console.log(r.donnees.nom); // TypeScript sait que donnees existe
  } else {
    console.error(r.erreur);    // et ici, qu'il n'existe pas
  }
}

function formater(valeur: number, decimales = 2): string {
  return valeur.toFixed(decimales);
}

function premier<T>(elements: T[]): T | undefined {
  return elements[0];
}

const n = premier([1, 2, 3]);        // number | undefined
const s = premier(["a", "b"]);      // string | undefined

